fn initialize_session(
        &mut self,
        request: &TissueRequest,
        window: &crate::cc_render::office::timeline::MotionWindow,
    ) -> anyhow::Result<()> {
        let start = window
            .knots
            .first()
            .ok_or_else(|| anyhow::anyhow!("empty tissue motion window"))?
            .pts_ms as f64;
        let frames = self.frames_at(&window.knots, start)?;
        self.solvers = request
            .asset
            .regions
            .iter()
            .zip(frames)
            .map(|(r, f)| r.solver(f))
            .collect::<Result<_, _>>()?;
        self.session = Some(window.session.clone());
        self.origin_ms = start;
        self.tick = 0;
        self.report_ms = 0;
        self.motion_initialized = false;
        self.morph_history = Default::default();
        Ok(())
    }fn solver() -> ClothSolverfn default() -> Selffn frames_at( &self, knots: &[crate::cc_render::renderer::SkeletalPose], at: f64, ) -> anyhow::Result<Vec<Frame>>
